void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    // Prevent activity overflow by scaling down all activities when the next addition would exceed the limit
    if (activity[var] + inc > 1e100) {
        const double scale = 1e-90;               // bring values back into a safe range
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }
    activity[var] += inc;
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
